  window.LESSONS["u2_l05"] = {"meta":{"grade":2,"subject":"국어","term":2,"unit":2,"unit_title":"서로 존중해요","n":5,"covers":"5·6차시","title":"상황에 알맞게 고운 말로 대화하기","goal":"고운 말로 대화할 수 있다.","std":"[2국01-06]","duration_min":80,"lesson_format":"묶음 차시(5·6차시 연속 80분 · 적용) · 2세대 19장(7요소)","theme":"곰이·펭이 고운 말 교실","live_url":"../../grade2/semester2/korean/2단원_서로존중해요/g2_kor_u2_l05_06.html","source":"grade2/semester2/korean/2단원_서로존중해요/g2_kor_u2_l05_06.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"상황에 알맞게\n고운 말로 대화하기","emoji":"🎭"},"suggested_extras":["v_l3_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 **욕설·비속어를 쓰지 않고**, 상대의 **기분을 살피며** 말하고, **공감하며** 들어 주는 방법을 배웠어요.","items":[{"q":"예절에 어긋나게 대상을 낮추어 보거나 하찮게 여기는 말을 무엇이라고 하나요?","a":"비속어"},{"q":"고운 말로 대화하는 방법 한 가지를 말해 볼까요?","a":"상대의 기분이 상하지 않도록 말하기 · 상대의 말을 공감하며 들어 주기 등"},{"q":"친구와 생각이 다를 때에도 고운 말로 말할 수 있을까요?","a":"네, 상대의 기분이 상하지 않게 내 생각을 말할 수 있어요"}],"from":"u2_l03"},"suggested_extras":["q_l3_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"아침 현관의 인사","kids":[{"face":"🐻","label":"곰이\n\"할머니, 학교 다녀오겠습니다!\""},{"face":"🐧","label":"펭이\n\"곰이는 할머니께 정말 공손하게 말하네!\""}],"question":"곰이는 친구에게 말할 때와 할머니께 말씀드릴 때 말이 조금 달라요. 누구에게, 어떤 상황에서 말하느냐에 따라 알맞은 고운 말이 달라질까요?","img":"assets/photo/korean/family_morning_greeting.jpg","tnote":{"ask":["친구에게 말할 때와 웃어른께 말씀드릴 때 무엇이 다른가요?","오늘 아침 집을 나설 때 어떤 말을 했나요?"],"watch":"","min":5}},"suggested_extras":["q_l3_2","r_l3_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"가 — 발표 차례 정하기","emoji":"🗣️"},{"name":"나 — 만든 것 칭찬하기","emoji":"🧸"},{"name":"다 — 생일 선물에 고마움 전하기","emoji":"🎁"}]},"title":"대화하는 상황을 생각하며 그림을 살펴봐요","content":"가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」\n나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」\n다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」","tnote":{"ask":["세 그림은 저마다 어떤 상황인가요?","그림 다에서 손자의 말이 친구에게 하는 말과 다른 점은?"],"watch":"누가 말하는지 보지 않고 말만 읽는 경우 — 누가 누구에게 말하는지 먼저 짚을 것","min":8}},"src":1,"suggested_extras":["e_l3_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"학교에 올 때","emoji":"🎒"},{"name":"학교에서","emoji":"🏫"},{"name":"집에서","emoji":"🏠"}]},"title":"고운 말로 대화를 나눈 경험을 말해 봐요","content":"🗣️ 학교에 올 때, 학교에서, 집에서 누구와 어떤 고운 말을 주고받았는지 친구들 앞에서 바른 자세로 말해 보세요.","tnote":{"ask":["오늘 누구와 어떤 고운 말을 주고받았나요?","친구들 앞에서 말할 때 어떤 자세로 말할까요?"],"watch":"고운 말 없이 일만 이야기하는 경우 — 그때 한 말을 그대로 떠올리게 할 것","min":8}},"src":5,"suggested_extras":["t_l3_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"chain","items":[{"name":"상황 하나 고르기","emoji":"🎭"},{"name":"짝과 역할 나누기","emoji":"👥"},{"name":"고운 말로 대화하기","emoji":"🌸"}]},"title":"상황을 하나 골라 짝과 역할놀이를 해 봐요","content":"🎭 그림 가·나·다 가운데 한 상황을 골라 짝과 역할을 나누어 고운 말로 대화해 보세요.","tnote":{"ask":["어떤 상황을 골랐나요?","역할을 바꾸어 해 보니 어떤 점이 달랐나요?"],"watch":"장난스럽게만 하는 경우 — 상황 속 인물의 마음을 먼저 떠올리게 할 것","min":10}},"src":9,"suggested_extras":["e_l3_2","t_l3_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"sort2","a":{"name":"😣 기분이 상하는 말","items":["너랑 다시는 안 놀아!","혼자 알아서 해."]},"b":{"name":"😊 마음을 헤아린 고운 말","items":["기다리느라 힘들었어. 다음부터는 좀 일찍 오면 좋겠어.","다리를 다쳐서 힘들지? 내가 문을 열어 줄게."],"hint":"듣는 사람의 처지를 생각해요"}},"title":"역할놀이를 하고 나서 든 생각이나 느낌을 나눠요","content":"💬 고운 말로 대화하고 나서 어떤 생각이나 느낌이 들었나요? 친구들과 이야기해 보세요.","tnote":{"ask":["역할놀이를 하고 나서 어떤 생각이나 느낌이 들었나요?","두 칸의 말은 무엇이 다른가요?"],"watch":"","min":6}},"src":11,"suggested_extras":["q_l3_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"웃어른께도 친구에게 하듯이 **편하게** 말하면 된다.","right":"웃어른께는 「축하해 주셔서 고맙습니다.」처럼 **높임말**을 써서 공손하게 말해요. 친구에게 하는 말과 웃어른께 드리는 말은 달라요. 누구에게 말하는지 생각해서 상황에 알맞은 고운 말을 골라요.","hint":"「생일 축하해 줘서 고마워.」와 「생일을 축하해 주셔서 고맙습니다.」를 나란히 들려주고, 할머니께는 어느 쪽이 알맞은지 물어보세요.","tnote":{"ask":["할머니께는 어떤 말로 고마움을 전할까요?","친구에게 할 때와 무엇이 달라졌나요?"],"watch":"「고마워」로만 말하는 경우","min":4}},"suggested_extras":["x_l3_1","x_l3_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🖼️","body":"곰이가 세 그림을 보며 누가 어떤 상황에서 말하는지 살펴보고 있어요."},"question":"그림과 상황을 이어 봐요","answer":"🅰️그림 가 ↔ 친구와 친구 — 국어 시간에 누가 발표할지 이야기해요 / 🅱️그림 나 ↔ 친구와 친구 — 함께 장난감으로 놀아요 / 🅲그림 다 ↔ 할머니와 손자 — 할머니께서 생일 선물을 주세요","note":"풀이: 누가 누구에게 말하는지 먼저 살펴요."},"src":2,"suggested_extras":["t_l3_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🩼","body":"펭이의 친구가 다리를 다쳤어요."},"question":"다리를 다친 친구가 「운동장에 나가고 싶어.」라고 해요. 알맞은 고운 말은?","options":[{"text":"다리도 아픈데 왜 나가?"},{"text":"혼자 알아서 해."},{"text":"다리를 다쳐서 힘들지? 내가 문을 열어 줄게.","correct":true}],"note":"풀이: 친구의 처지를 헤아려 도와주는 말을 골라요. → **다리를 다쳐서 힘들지? 내가 문을 열어 줄게.**"},"src":6,"suggested_extras":["e_l3_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"📱","body":"곰이가 휴대 전화를 오래 하다가 아빠의 말씀을 들었어요."},"question":"아빠께서 「아직도 휴대 전화를 하고 있네.」 하셨어요. 알맞은 대답은?","options":[{"text":"…… (못 들은 척한다)"},{"text":"아빠, 제가 휴대 전화를 너무 오랫동안 했네요. 이제 책 읽을게요.","correct":true},{"text":"아빠는 상관하지 마세요."}],"note":"풀이: 높임말로 내 잘못을 알고 대답한 것을 골라요. → **아빠, 제가 휴대 전화를 너무 오랫동안 했네요. 이제 책 읽을게요.**"},"src":8,"suggested_extras":["q_l3_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"「제 생일을 축하해 주셔서 ○○○○○.」 빈칸에 알맞은 말을 넣어 읽어 봐요.","a":"고맙습니다","steps":["할머니께 드린 말씀을 떠올린다","빈칸에 높임말을 넣는다","문장을 끝까지 소리 내어 읽는다"]},"도전":{"q":"늦게 온 친구에게 내 마음을 솔직하게, 기분이 상하지 않게 「~해서 ~했어. 다음부터는 ~면 좋겠어.」 꼴로 말해 봐요.","a":"여러 답 (예: 기다리느라 걱정했어. 다음부터는 늦으면 미리 말해 주면 좋겠어.)","steps":["기다리는 동안 든 마음을 떠올린다","바라는 점을 정한다","말 틀에 넣어 끝까지 말한다"]},"심화":{"q":"선생님께서 「숙제를 잘해 왔구나.」 하고 칭찬하셨어요. 높임말을 써서 고운 말로 대답해 봐요.","a":"여러 답 (예: 칭찬해 주셔서 감사합니다. 다음에도 열심히 할게요.)","open":true}},"tnote":{"ask":["기본에서 빈칸을 채워 끝까지 읽었나요?","심화에서 어떻게 대답했나요?"],"watch":"도전에서 화를 내듯 말하는 경우 — 바라는 점을 부드럽게 말하게 할 것","min":8}},"suggested_extras":["q_l3_5","g_l3_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"상황 카드 역할놀이","type":"pair","goal":"짝과 「다친 친구」·「늦게 온 친구」·「아빠의 말씀」 상황 카드 가운데 하나를 골라 역할을 나누고, 상황에 알맞은 고운 말로 대화한 뒤 역할을 바꾸어 다시 하기","steps":["상황 카드 하나를 고른다","누가 누구 역할을 할지 정한다","상황에 알맞은 고운 말로 대화한다","역할을 바꾸어 다시 하고 서로 잘한 점을 말한다"],"solo":["상황 카드를 하나씩 뒤집는다","두 사람의 말을 혼자서 번갈아 소리 내어 말하고, 웃어른께 하는 말은 높임말인지 확인한다"],"materials":["상황 카드 3장","역할 이름표 2개"],"minutes":20,"tnote":{"ask":["짝이 가장 잘한 고운 말은 무엇이었나요?","역할을 바꾸어 보니 어떤 마음이 들었나요?"],"watch":"대사만 읽고 끝내는 경우 — 상대 말을 듣고 대답하게 할 것","min":20}},"suggested_extras":["g_l3_2","t_l3_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"등굣길 인사","scenario":{"icon":"🎒","body":"아침에 집을 나설 때 「학교 다녀오겠습니다.」 하고 인사하고, 학교에서 친구를 만나면 「안녕! 오늘도 재미있게 놀자.」 하고 말해 보아요. 누구에게 말하느냐에 따라 알맞은 말을 고르면 하루가 기분 좋게 시작돼요."},"content":"**누구와 어떤 상황**인지 생각해서 알맞은 고운 말로 대화해요. 웃어른께는 **높임말**로 공손하게 말해요."},"suggested_extras":["r_l3_2","r_l3_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"곰이가 할머니께 생일 선물을 받고 「와, 고마워!」라고 말했어요.","challenge":"곰이의 말에서 아쉬운 점을 찾아보고, 할머니께 알맞은 고운 말로 바꾸어 말해 봐요.","note":"풀이: 고마운 마음은 좋지만 웃어른께는 **높임말**로 말씀드려요 — 「할머니, 제 생일을 축하해 주셔서 고맙습니다.」처럼 말해요.","tnote":{"ask":["곰이의 말에서 무엇이 아쉬울까요?","할머니께 어떻게 말씀드리면 좋을까요?"],"watch":"「고마워」도 고운 말이라 괜찮다고 하는 경우","min":5}},"suggested_extras":["t_l3_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"알맞은 고운 말을 고르려면 무엇을 먼저 생각해야 할까요?","a":"누구와 어떤 상황에서 대화하는지"},{"q":"웃어른께 고마움을 전할 때는 어떤 말을 쓰나요?","a":"높임말 (예: 고맙습니다)"},{"q":"다리를 다친 친구에게 알맞은 고운 말은 무엇일까요?","a":"다리를 다쳐서 힘들지? 내가 문을 열어 줄게."}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["상대의 말을 공감하며 들었어요.","상대의 기분을 살피며 말했어요.","상황에 알맞은 대화를 나누었어요.","곰이는 할머니께 「축하해 주셔서 고맙습니다.」 하고 공손하게 인사하고, 펭이에게는 「오늘도 재미있게 놀자!」 하고 웃었다."],"arrows":["누구와 · 어떤 상황","알맞은 고운 말 고르기","다음: 칭찬이나 조언하기"]},"suggested_extras":["r_l3_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 상황에 따라 알맞은 고운 말이 다르다는 것을 말할 수 있나요?","🔧 과정·기능 — 역할놀이에서 상황에 알맞은 고운 말로 대화할 수 있나요?","💛 가치·태도 — 웃어른께 공손하게 말씀드렸나요?"],"prompts":["역할놀이에서 가장 기억에 남는 말은 무엇인가요?"]},"suggested_extras":["e_l3_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"칭찬이나 조언을 해 봐요. 힘도 세고 달리기도 잘하는데 친구가 없어 속상한 동물이 있대요. 어떻게 도와줄까요?","emoji":"🐊"},"suggested_extras":["c_l3_1"]}],"extras":[{"id":"v_l3_1","type":"video","icon":"🎥","title":"상황에 맞는 고운 말 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+2%ED%95%99%EB%85%84+%EA%B5%AD%EC%96%B4+%EC%83%81%ED%99%A9%EC%97%90+%EC%95%8C%EB%A7%9E%EC%9D%80+%EA%B3%A0%EC%9A%B4+%EB%A7%90+%EC%97%AD%ED%95%A0%EB%86%80%EC%9D%B4","description":"여러 상황에서 고운 말로 대화하는 모습(교사가 먼저 확인).","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l3_1","type":"fun_question","icon":"💡","title":"기분 좋은 대화","content":"가족이나 친구와 가장 기분 좋게 나눈 대화는?","fit_slides":["concept","basic_problem"]},{"id":"q_l3_2","type":"fun_question","icon":"💡","title":"누구에게","content":"할머니께 말씀드릴 때와 친구에게 말할 때 무엇이 다를까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l3_3","type":"fun_question","icon":"💡","title":"세 그림","content":"그림 가 · 나 · 다는 저마다 어떤 상황인가요?","fit_slides":["concept","basic_problem"]},{"id":"q_l3_4","type":"fun_question","icon":"💡","title":"늦은 친구","content":"친구가 늦게 오면 어떻게 말하면 좋을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l3_5","type":"fun_question","icon":"💡","title":"역할 바꾸기","content":"역할을 바꾸어 해 보니 어떤 점이 달랐나요?","fit_slides":["concept","basic_problem"]},{"id":"t_l3_1","type":"tip","icon":"🧩","title":"누가 누구에게","content":"그림마다 누가 누구에게 말하는지 화살표로 표시하세요.","fit_slides":["concept","misconception"]},{"id":"t_l3_2","type":"tip","icon":"🧩","title":"바른 자세","content":"경험을 발표할 때 듣는 친구들을 바라보며 말하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l3_3","type":"tip","icon":"🧩","title":"높임말 짚기","content":"웃어른께 드리는 말은 끝말이 어떻게 달라지는지 짚어 주세요.","fit_slides":["concept","misconception"]},{"id":"t_l3_4","type":"tip","icon":"🧩","title":"역할 바꾸기","content":"역할놀이는 꼭 역할을 바꾸어 두 번 하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l3_5","type":"tip","icon":"🧩","title":"다음 시간 예고","content":"다음 시간은 칭찬이나 조언을 해 봐요.","fit_slides":["concept","misconception"]},{"id":"r_l3_1","type":"real_world","icon":"🌍","title":"등굣길 인사","content":"집을 나설 때와 친구를 만날 때 알맞게 인사해요.","fit_slides":["real_world","summary"]},{"id":"r_l3_2","type":"real_world","icon":"🌍","title":"선물 받을 때","content":"선물을 받으면 받은 사람에 맞게 고마움을 전해요.","fit_slides":["real_world","summary"]},{"id":"r_l3_3","type":"real_world","icon":"🌍","title":"가족 대화","content":"저녁에 가족과 고운 말로 하루 이야기를 나눠요.","fit_slides":["real_world","summary"]},{"id":"g_l3_1","type":"game","icon":"🎮","title":"상황 카드 역할놀이","content":"상황 카드를 뽑아 짝과 고운 말로 대화해요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l3_2","type":"game","icon":"🎮","title":"어울리는 대답 찾기","content":"먼저 한 말에 어울리는 대답 카드를 찾아요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l3_1","type":"misconception","icon":"⚠️","title":"편한 말","content":"웃어른께도 친구처럼 말하는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l3_2","type":"misconception","icon":"⚠️","title":"솔직하면 다 돼","content":"솔직하면 화를 내며 말해도 된다고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l3_1","type":"example","icon":"📝","title":"세 그림 판","content":"그림 가 · 나 · 다 상황 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l3_2","type":"example","icon":"📝","title":"경험 판","content":"학교에 올 때 · 학교에서 · 집에서 세 칸 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l3_3","type":"example","icon":"📝","title":"상황 카드","content":"다친 친구 · 늦게 온 친구 · 아빠의 말씀 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l3_1","type":"checklist","icon":"✅","title":"다음 차시 준비","content":"교과서 52~56쪽. 다음 시간은 칭찬이나 조언을 해 봐요.","fit_slides":["next_lesson"]}]};
